use std::process::ExitCode;

use wgpu::util::DeviceExt;

const SHADER: &str = r#"
struct Params {
    width: u32,
    height: u32,
};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(8, 8, 1)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    let x = id.x;
    let y = id.y;
    let w = params.width;
    let h = params.height;
    if (x >= w || y >= h) {
        return;
    }
    let xl = select(x - 1u, x, x == 0u);
    let xr = select(x + 1u, x, x + 1u >= w);
    let yu = select(y - 1u, y, y == 0u);
    let yd = select(y + 1u, y, y + 1u >= h);
    let row = y * w;
    let c = src[row + x];
    let sum = 4u * c + src[row + xl] + src[row + xr] + src[yu * w + x] + src[yd * w + x];
    dst[row + x] = sum / 8u;
}
"#;

const WORKGROUP: u32 = 8;

struct Grid {
    width: usize,
    height: usize,
    steps: usize,
    cells: Vec<u32>,
}

fn parse(text: &str) -> Result<Grid, String> {
    let mut tokens = text.split_ascii_whitespace();
    let mut next = |what: &str| -> Result<u64, String> {
        let tok = tokens
            .next()
            .ok_or_else(|| format!("unexpected end of input reading {what}"))?;
        tok.parse::<u64>()
            .map_err(|_| format!("invalid number {tok:?} for {what}"))
    };
    let width = next("width")?;
    let height = next("height")?;
    let steps = next("steps")?;
    if !(1..=512).contains(&width) || !(1..=512).contains(&height) {
        return Err(format!("width and height must be 1..=512, got {width}x{height}"));
    }
    if steps > 1000 {
        return Err(format!("steps must be 0..=1000, got {steps}"));
    }
    let (width, height, steps) = (width as usize, height as usize, steps as usize);
    let mut cells = Vec::with_capacity(width * height);
    for i in 0..width * height {
        let v = next(&format!("cell at row {}, column {}", i / width, i % width))?;
        if v > 1_000_000 {
            return Err(format!("cell value {v} exceeds 1000000"));
        }
        cells.push(v as u32);
    }
    if tokens.next().is_some() {
        return Err("extra data after the grid".to_string());
    }
    Ok(Grid {
        width,
        height,
        steps,
        cells,
    })
}

async fn run_gpu(grid: &Grid) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::new(&wgpu::InstanceDescriptor::default());
    let adapter = instance
        .request_adapter(&wgpu::RequestAdapterOptions {
            power_preference: wgpu::PowerPreference::HighPerformance,
            force_fallback_adapter: false,
            compatible_surface: None,
        })
        .await
        .map_err(|e| format!("no GPU adapter: {e}"))?;
    let (device, queue) = adapter
        .request_device(&wgpu::DeviceDescriptor::default())
        .await
        .map_err(|e| format!("cannot open GPU device: {e}"))?;

    let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("heat"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("heat"),
        layout: None,
        module: &shader,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });

    let size = (grid.cells.len() * std::mem::size_of::<u32>()) as wgpu::BufferAddress;
    let params = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: bytemuck::cast_slice(&[grid.width as u32, grid.height as u32]),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let usage =
        wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC | wgpu::BufferUsages::COPY_DST;
    let buffers = [
        device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("grid a"),
            contents: bytemuck::cast_slice(&grid.cells),
            usage,
        }),
        device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("grid b"),
            size,
            usage,
            mapped_at_creation: false,
        }),
    ];
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let layout = pipeline.get_bind_group_layout(0);
    // bind_groups[i] reads buffers[i] and writes buffers[1 - i].
    let bind_groups: Vec<wgpu::BindGroup> = (0..2)
        .map(|i| {
            device.create_bind_group(&wgpu::BindGroupDescriptor {
                label: Some("heat"),
                layout: &layout,
                entries: &[
                    wgpu::BindGroupEntry {
                        binding: 0,
                        resource: params.as_entire_binding(),
                    },
                    wgpu::BindGroupEntry {
                        binding: 1,
                        resource: buffers[i].as_entire_binding(),
                    },
                    wgpu::BindGroupEntry {
                        binding: 2,
                        resource: buffers[1 - i].as_entire_binding(),
                    },
                ],
            })
        })
        .collect();

    let groups_x = (grid.width as u32).div_ceil(WORKGROUP);
    let groups_y = (grid.height as u32).div_ceil(WORKGROUP);
    let mut encoder = device.create_command_encoder(&Default::default());
    for step in 0..grid.steps {
        // Separate passes so each step sees the previous step's completed writes.
        let mut pass = encoder.begin_compute_pass(&Default::default());
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind_groups[step % 2], &[]);
        pass.dispatch_workgroups(groups_x, groups_y, 1);
    }
    let result = &buffers[grid.steps % 2];
    encoder.copy_buffer_to_buffer(result, 0, &readback, 0, size);
    queue.submit([encoder.finish()]);

    let slice = readback.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("GPU poll failed: {e}"))?;
    rx.recv()
        .map_err(|e| format!("readback channel closed: {e}"))?
        .map_err(|e| format!("readback failed: {e}"))?;
    let out = bytemuck::cast_slice::<u8, u32>(&slice.get_mapped_range()).to_vec();
    readback.unmap();
    Ok(out)
}

fn main() -> ExitCode {
    let Some(path) = std::env::args().nth(1) else {
        eprintln!("usage: gpu_heat <input-file>");
        return ExitCode::from(2);
    };
    let text = match std::fs::read_to_string(&path) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("cannot read {path}: {e}");
            return ExitCode::from(1);
        }
    };
    let grid = match parse(&text) {
        Ok(g) => g,
        Err(e) => {
            eprintln!("bad input: {e}");
            return ExitCode::from(1);
        }
    };
    let cells = match pollster::block_on(run_gpu(&grid)) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("GPU error: {e}");
            return ExitCode::from(1);
        }
    };

    let mut out = String::with_capacity(cells.len() * 8 + 32);
    for row in cells.chunks(grid.width) {
        let line: Vec<String> = row.iter().map(u32::to_string).collect();
        out.push_str(&line.join(" "));
        out.push('\n');
    }
    let sum: u64 = cells.iter().map(|&v| u64::from(v)).sum();
    out.push_str(&format!("SUM {sum}\n"));
    use std::io::Write;
    if let Err(e) = std::io::stdout().lock().write_all(out.as_bytes()) {
        eprintln!("cannot write output: {e}");
        return ExitCode::from(1);
    }
    ExitCode::SUCCESS
}
